import json
H,W=18,27
g=[[5]*W for _ in range(H)]
for r,cs in [(5,[3,5]),(15,[9,11,13,15,17,19,21]),(17,[15,17,19])]:
 for c in cs:g[r][c]=7
for r in range(H):
 for c in range(1,W-1):
  if g[r][c-1]==g[r][c+1]==7:g[r][c]=2
assert len(g)==18 and all(len(row)==27 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

